package dev.jdcm.update

import org.junit.jupiter.api.Assertions.assertEquals
import org.junit.jupiter.api.Assertions.assertFalse
import org.junit.jupiter.api.Assertions.assertNotNull
import org.junit.jupiter.api.Assertions.assertNull
import org.junit.jupiter.api.Assertions.assertTrue
import org.junit.jupiter.api.Test

class UpdateCoreTest {
    /** EXACTLY what release.yml's jq writes (generated by running that step). Keep them in sync. */
    private val written = """
        {
          "versionCode": 42,
          "versionName": "0.2.0-alpha",
          "tag": "v0.2.0-alpha",
          "apk": "https://github.com/OWNER/REPO/releases/download/v0.2.0-alpha/myapp.apk",
          "assetId": 312345678,
          "size": 9,
          "sha256": "1e10ba560383b17472b4cf72fef8f9e76c66815a3e6ae8c5a9b0c5e696b0bdf8",
          "notes": { "en": "• Faster sync", "es": "• Sincroniza más rápido" }
        }
    """.trimIndent()

    @Test
    fun `the shape release yml writes is the shape this parses`() {
        val m = ChannelManifest.parse(written)!!
        assertEquals(42, m.versionCode)
        assertEquals("0.2.0-alpha", m.versionName)
        assertEquals(312345678L, m.assetId)
        assertTrue(m.verifiable(maxBytes = 100))
        assertEquals("• Sincroniza más rápido", m.notesFor("es"))
        assertEquals("• Faster sync", m.notesFor("fr"))
    }

    @Test
    fun `unknown keys and broken notes never lose the manifest`() {
        val m = ChannelManifest.parse("""{"versionCode":7,"apk":"x","future":{"a":1},"notes":["not","a","map"]}""")
        assertNotNull(m)
        assertEquals(7, m!!.versionCode)
        assertTrue(m.notes.isEmpty())
        assertNull(ChannelManifest.parse("<html>captive portal</html>"))
    }

    @Test
    fun `a manifest without size or digest is not verifiable`() {
        val m = ChannelManifest.parse(written)!!
        assertFalse(m.copy(size = 0).verifiable(100))
        assertFalse(m.copy(sha256 = "abc").verifiable(100))
        assertFalse(m.verifiable(maxBytes = 8)) // larger than the cap
    }

    @Test
    fun `rejection reasons, in order`() {
        fun r(pkg: String? = "dev.jdcm", vc: Int? = 43, vn: String? = "0.3.0-alpha", installed: Int = 42, manifest: Int? = 43) =
            rejectionReason(pkg, vc, vn, "dev.jdcm", installed, UpdateChannel.ALPHA, manifest)
        assertNull(r())
        assertEquals("not a readable APK", r(pkg = null))
        assertEquals("belongs to com.evil", r(pkg = "com.evil"))
        assertEquals("version 42 is not newer than 42", r(vc = 42))
        assertEquals("version 43, manifest said 44", r(manifest = 44))
        assertEquals("\"0.3.0-beta\" is not a alpha build", r(vn = "0.3.0-beta"))
        assertEquals("\"0.3.0\" is not a alpha build", r(vn = "0.3.0")) // no suffix: belongs to neither channel
    }

    @Test
    fun `a staged file must be exactly the build on offer`() {
        val m = ChannelManifest.parse(written)!!
        assertTrue(stagedIsCurrent(42, 9, m.sha256.uppercase(), m))
        assertFalse(stagedIsCurrent(41, 9, m.sha256, m))
        assertFalse(stagedIsCurrent(42, 10, m.sha256, m))
        assertFalse(stagedIsCurrent(null, 9, m.sha256, m))
    }

    @Test
    fun `only this repo's release downloads are trusted`() {
        val repo = "OWNER/REPO"
        assertTrue(trustedApkUrl("https://github.com/OWNER/REPO/releases/download/v1.0.0-beta/myapp.apk", repo))
        assertFalse(trustedApkUrl("http://github.com/OWNER/REPO/releases/download/v1/myapp.apk", repo))
        assertFalse(trustedApkUrl("https://github.com.evil.io/OWNER/REPO/releases/download/v1/myapp.apk", repo))
        assertFalse(trustedApkUrl("https://github.com/OWNER/REPO/releases/download/../../../evil/x/releases/download/a.apk", repo))
        assertFalse(trustedApkUrl("https://github.com/OWNER/REPO-evil/releases/download/v1/myapp.apk", repo))
        assertFalse(trustedApkUrl("not a url", repo))
    }

    @Test
    fun `choosing a channel says what will happen`() {
        assertEquals(ChannelSwitch.Unknown, channelSwitch(42, 0, ""))
        assertEquals(ChannelSwitch.Immediate("0.3.0-alpha"), channelSwitch(42, 43, "0.3.0-alpha"))
        assertEquals(ChannelSwitch.AlreadyOnIt, channelSwitch(42, 42, "0.2.0-beta"))
        assertEquals(ChannelSwitch.WaitsForNextRelease("0.1.0-beta"), channelSwitch(42, 30, "0.1.0-beta"))
    }

    @Test
    fun `holds after an install that did not happen`() {
        assertEquals(Long.MAX_VALUE, holdUntil(InstallSetback.SIGNATURE_CONFLICT, 1_000))
        assertEquals(1_000 + 24 * 3_600_000L, holdUntil(InstallSetback.DECLINED, 1_000))
        assertTrue(keepsApkAfter(InstallSetback.DECLINED))
        assertFalse(keepsApkAfter(InstallSetback.STORAGE))
    }

    @Test
    fun `newer needs somewhere to download from`() {
        val m = ChannelManifest.parse(written)!!
        assertTrue(m.isNewerThan(41))
        assertFalse(m.isNewerThan(42))
        assertFalse(m.copy(apk = "", assetId = 0).isNewerThan(1))
    }
}
